function checkOverloadTransition(before,after,index){
 const a=before?.semesters[index],b=after?.semesters[index];if(!a||!b)return;
 const prior=semesterUnits(a,catalogue),next=semesterUnits(b,catalogue),oldCount=semesterCourseCount(a),newCount=semesterCourseCount(b);
 if((prior<=8&&next>8)||(oldCount<5&&newCount>=5)){
  const {year,term}=semesterFor(after,index);
  overloadNotice=`${year} S${term} 已安排 ${newCount} 门、${next} 学分。UQ 通常允许最近一次全日制学期 GPA 达到 4.5 或以上的学生修读 10 学分；${index===0?'如果这是首次全日制学期，需要特别核实首学期超修资格。':''}具体超修资格或例外申请请向 UQ 核实。可以先保留此规划。`;
 }
}
function overloadWarnings(d,catalogue){return d.semesters.flatMap((sem,i)=>{const units=semesterUnits(sem,catalogue);return units>8?[`第 ${i+1} 学期安排 ${units} 学分；修读 10 学分通常要求最近全日制学期 GPA ≥ 4.5，具体资格请向 UQ 核实。`]:[]})}
